using System;using System.Drawing;using System.Windows.Forms;using System.IO;using System.Linq;using System.Numerics;using System.Reflection;using System.Globalization;using CircuitoStudio;
class FaultLoopsTests {
static int n;static void Check(bool ok,string label){n++;if(!ok)throw new Exception(label);}static void Near(double a,double b,string s){Check(Math.Abs(a-b)<=1e-9*Math.Max(1,Math.Abs(b)),s);}static void Equal(Complex a,Complex b,string s){Near(a.Real,b.Real,s+" real");Near(a.Imaginary,b.Imaginary,s+" imag");}static void Reject(Action action,string s){bool bad=false;try{action();}catch(InvalidDataException){bad=true;}Check(bad,s);}static CircuitConductors W(bool pen=false){return new CircuitConductors{Connection=LiveConnection.ThreePhaseNeutral,HasNeutral=!pen,HasPE=!pen,HasPEN=pen,Insulation=EquipmentInsulation.ClassI,Reference="Ligação QA"};}
static ReturnConductorRating R(ReturnRole role,double r,double x){return new ReturnConductorRating{Role=role,Material=ConductorMaterial.Copper,SectionMm2=35,CorrectedIzA=100,ResistanceOhmKm=r,ReactanceOhmKm=x,Reference="QA-"+role,Source="QA equivalente",DataVersion="2026.10",Conditions="R/X por condutor60Hz; mesma rota"};}
static ReturnSizingBinding Ret(bool pen=false){return new ReturnSizingBinding{Engine=ReturnSizing.EngineId,Requirements=new ReturnSizingRequirements(),Neutral=pen?null:R(ReturnRole.Neutral,2,.2),Protective=R(pen?ReturnRole.PEN:ReturnRole.PE,pen?4:3,pen?.4:.3)};}
static Project Fixture(EarthingScheme scheme){var p=new Project();p.Source.LineVoltage=400;p.Source.ShortCircuitKA=10;var b=new Board{Id="Q",Voltage=400};var c=new Circuit{Id="C",Voltage=400,Phases=PhaseMode.Trifasico,PhaseLabel="ABC",PowerKw=10,CableMm2=35,LengthM=100};c.Cable.ResistanceOhmKm=1;c.Cable.ReactanceOhmKm=.1;c.Cable.Reference="Cabo QA";p.Boards.Add(b);b.Circuits.Add(c);p.GroundingSource=new GroundingSource{Scheme=scheme,NeutralConnection=scheme==EarthingScheme.IT?NeutralEarthConnection.Isolated:NeutralEarthConnection.Direct,NeutralDistributed=true,InstallationRaOhm=100,SourceRbOhm=2,Reference="QA",DataVersion="2026.10",Conditions="Grupo comum; elétrodos série quando TT"};p.Earthing=Grounding.Name(scheme);bool pen=scheme==EarthingScheme.TNC||scheme==EarthingScheme.TNCS;c.Conductors=W(pen);c.ReturnSizing=Ret(pen);p.LoopSource=new LoopSource{LineVoltageV=400,FrequencyHz=60,PhaseROhm=.1,PhaseXOhm=.2,NeutralROhm=.3,NeutralXOhm=.4,PEROhm=.5,PEXOhm=.6,PENROhm=.7,PENXOhm=.8,ITConductanceSiemensPerPhase=.001,ITCapacitanceNFPerPhase=0,ITNeutralConductanceSiemens=0,ITNeutralCapacitanceNF=0,Reference="Estrela desacoplada QA",DataVersion="2026.10",Conditions="Fonte e R/X referidos ao mesmo barramento/frequência; fugas IT concentradas por fase"};p.Validate();return p;}
static LoopFaultCase F(LoopFaultKind kind){return new LoopFaultCase{Kind=kind,Live=FaultLive.L1,Reference="Caso sintético QA",Conditions="Nominal, sem arco; Zf=0 declarado"};}
static void Save(Project p,Circuit c,LoopFaultCase fault,string folder,string name){c.LoopFault=fault.Copy();p.Save(Path.Combine(folder,name+".circuito"));var result=FaultLoops.Evaluate(p,c,fault);Check(result.Current.HasValue,"saved case calculable "+name);string file=Path.Combine(folder,"resultados.csv");if(!File.Exists(file))File.WriteAllText(file,"Case;Circuit;Kind;IRealA;IImagA;ZRealOhm;ZImagOhm;MetalV;MetalReference;StarRealV;StarImagV\r\n");Func<double,string> fmt=x=>x.ToString("R",CultureInfo.InvariantCulture);File.AppendAllText(file,name+";"+c.Id+";"+fault.Kind+";"+fmt(result.Current.Value.Real)+";"+fmt(result.Current.Value.Imaginary)+";"+(result.LoopImpedance.HasValue?fmt(result.LoopImpedance.Value.Real):"")+";"+(result.LoopImpedance.HasValue?fmt(result.LoopImpedance.Value.Imaginary):"")+";"+(result.MetalVoltageV.HasValue?fmt(result.MetalVoltageV.Value):"")+";"+result.MetalReference+";"+(result.BusVoltages!=null?fmt(result.BusVoltages[3].Real):"")+";"+(result.BusVoltages!=null?fmt(result.BusVoltages[3].Imaginary):"")+"\r\n");File.WriteAllText(Path.Combine(folder,name+".txt"),result.Detail);}
