p=Fixture(EarthingScheme.TT);c=p.Boards[0].Circuits[0];c.LengthM=0;p.Source.LineVoltage=p.LoopSource.LineVoltageV=p.Boards[0].Voltage=c.Voltage=230*Math.Sqrt(3);p.LoopSource.PhaseROhm=p.LoopSource.PhaseXOhm=p.LoopSource.PEROhm=p.LoopSource.PEXOhm=0;p.GroundingSource.InstallationRaOhm=20;p.GroundingSource.SourceRbOhm=10;result=FaultLoops.Evaluate(p,c,f);Near(result.CurrentA.Value,230d/30,"TT published rounded reference7.7A");Near(result.MetalVoltageV.Value,230d/30*20,"TT mass153.333V");Check(result.MetalReference==FaultVoltageReference.RemoteEarth,"TT remote earth reference");Save(p,c,f,folder,"tt-reference");p.GroundingSource.SourceRbOhm=null;Check(!FaultLoops.Evaluate(p,c,f).Current.HasValue,"TT Rb missing pending");p.GroundingSource.SourceRbOhm=0;p.GroundingSource.InstallationRaOhm=0;Check(!FaultLoops.Evaluate(p,c,f).Current.HasValue,"ideal zero loop no infinity");
p=Fixture(EarthingScheme.TNCS);var root=p.Boards[0];c=root.Circuits[0];var b=new Board{Id="B",Voltage=400,Name="Separação"};p.Boards.Add(b);var feed=DiagramEditing.Connect(p,root,b);root.Circuits.Remove(c);b.Circuits.Add(c);b.SeparatesPEN=true;c.Conductors=W();c.ReturnSizing=Ret();feed.LengthM=50;feed.Cable.ResistanceOhmKm=1;feed.Cable.ReactanceOhmKm=.1;feed.Cable.Reference="Feeder QA";feed.Conductors=W(true);feed.ReturnSizing=Ret(true);p.Validate();result=FaultLoops.Evaluate(p,c,f);Equal(result.LoopImpedance.Value,new Complex(1.45,1.065),"TNCS PEN then PE path exact");Save(p,c,f,folder,"tncs-split");
p=Fixture(EarthingScheme.IT);c=p.Boards[0].Circuits[0];c.LengthM=0;p.LoopSource.PhaseROhm=p.LoopSource.PhaseXOhm=p.LoopSource.NeutralROhm=p.LoopSource.NeutralXOhm=p.LoopSource.PEROhm=p.LoopSource.PEXOhm=0;f=F(LoopFaultKind.ITFirst);result=FaultLoops.Evaluate(p,c,f);double u0=400/Math.Sqrt(3);Equal(result.Current.Value,3*.001*u0/(1+3*.001*100),"IT resistive firstfault closed form");Near(result.MetalVoltageV.Value,Complex.Abs(result.Current.Value)*100,"IT first mass potential");Check(result.BusVoltages.Length==5&&result.MetalReference==FaultVoltageReference.RemoteEarth,"IT star displacement and reference explicit");Save(p,c,f,folder,"it-first-resistive");p.LoopSource.ITConductanceSiemensPerPhase=0;p.LoopSource.ITCapacitanceNFPerPhase=100;var y=new Complex(0,2*Math.PI*60*100e-9);result=FaultLoops.Evaluate(p,c,f);Equal(result.Current.Value,3*y*u0/(1+3*y*100),"IT capacitive firstfault analytical");Save(p,c,f,folder,"it-first-capacitive");p.LoopSource.ITNeutralCapacitanceNF=100;Equal(FaultLoops.Evaluate(p,c,f).Current.Value,4*y*u0/(1+4*y*100),"IT distributed neutral capacitance included");Save(p,c,f,folder,"it-first-neutral-capacitance");p.LoopSource.ITNeutralCapacitanceNF=null;Check(!FaultLoops.Evaluate(p,c,f).Current.HasValue,"unknown neutral leakage cannot be silently zero");p.LoopSource.ITNeutralCapacitanceNF=0;p.LoopSource.ITCapacitanceNFPerPhase=0;result=FaultLoops.Evaluate(p,c,f);Near(result.CurrentA.Value,0,"ideal isolated no leak zero current");Save(p,c,f,folder,"it-first-ideal");p.LoopSource.ITConductanceSiemensPerPhase=null;Check(!FaultLoops.Evaluate(p,c,f).Current.HasValue,"unknown leakage not zero");p.LoopSource.ITConductanceSiemensPerPhase=0;p.GroundingSource.NeutralConnection=NeutralEarthConnection.Impedance;p.GroundingSource.GroundingROhm=1000;p.GroundingSource.GroundingXOhm=0;p.GroundingSource.SourceRbOhm=0;result=FaultLoops.Evaluate(p,c,f);Equal(result.Current.Value,u0/1100,"IT impedance neutral firstfault");Save(p,c,f,folder,"it-first-grounded");p.Groun